mapper.delete:
DELETE FROM T_MP_ADJUST_RESULT
WHERE FACTORY_CODE = #{factoryCode} AND YEAR= #{year} AND MONTH= #{month}
AND VERSION= #{version}
AND STRUCTURE_NAME = #{structureName}

mapper.select:
SELECT DISTINCT
VERSION,
ADJUST_TYPE
FROM
T_MP_ADJUST_RESULT
WHERE
IS_DELETE = 0 AND VERSION IS NOT NULL
AND FACTORY_CODE = #{factoryCode}
AND YEAR = #{year}
AND MONTH = #{month}
AND ADJUST_TYPE = #{adjustType}
ORDER BY VERSION DESC

SELECT EXISTS(
    SELECT 1 FROM T_MP_ADJUST_RESULT
    WHERE IS_DELETE = 0
      AND YEAR = #{lastYear}
      AND MONTH = #{lastMonth}
      AND VERSION LIKE 'ADJ%'
    LIMIT 1
)

mapper.update:
UPDATE T_MP_ADJUST_RESULT f LEFT JOIN ( SELECT f5.FACTORY_CODE, f5.MATERIAL_CODE, f5.PRODUCT_STATUS, pv7.VERSION AS CURRENT_ADJ_VERSION, ( IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 1 THEN f5.DAY_1 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 2 THEN f5.DAY_2 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 3 THEN f5.DAY_3 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 4 THEN f5.DAY_4 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 5 THEN f5.DAY_5 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 6 THEN f5.DAY_6 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 7 THEN f5.DAY_7 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 8 THEN f5.DAY_8 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 9 THEN f5.DAY_9 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 10 THEN f5.DAY_10 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 11 THEN f5.DAY_11 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 12 THEN f5.DAY_12 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 13 THEN f5.DAY_13 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 14 THEN f5.DAY_14 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 15 THEN f5.DAY_15 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 16 THEN f5.DAY_16 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 17 THEN f5.DAY_17 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 18 THEN f5.DAY_18 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 19 THEN f5.DAY_19 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 20 THEN f5.DAY_20 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 21 THEN f5.DAY_21 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 22 THEN f5.DAY_22 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 23 THEN f5.DAY_23 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 24 THEN f5.DAY_24 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 25 THEN f5.DAY_25 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 26 THEN f5.DAY_26 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 27 THEN f5.DAY_27 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 28 THEN f5.DAY_28 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 29 THEN f5.DAY_29 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 30 THEN f5.DAY_30 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 31 THEN f5.DAY_31 ELSE 0 END, 0) ) AS PLAN_QTY, IFNULL(SUM(fin.DAY_QTY), 0) AS FINISH_QTY FROM T_MP_ADJUST_RESULT f5 -- 关联当月调整结果表，取当月各分厂最新ADJ版本号用于外层关联 INNER JOIN ( SELECT FACTORY_CODE, MAX(VERSION) AS VERSION FROM T_MP_ADJUST_RESULT WHERE IS_DELETE = 0 AND YEAR = #{currentYear} AND MONTH = #{currentMonth} AND VERSION LIKE 'ADJ%' GROUP BY FACTORY_CODE ) pv7 ON pv7.FACTORY_CODE = f5.FACTORY_CODE LEFT JOIN (
SELECT #{item.factoryCode} AS FACTORY_CODE, #{item.materialCode} AS MATERIAL_CODE, #{item.productStatus} AS PRODUCT_STATUS, #{item.stockCaptureDate} AS STOCK_CAPTURE_DATE
) stockMap ON stockMap.FACTORY_CODE = f5.FACTORY_CODE AND stockMap.MATERIAL_CODE = f5.MATERIAL_CODE AND IFNULL(stockMap.PRODUCT_STATUS, '') = IFNULL(f5.PRODUCT_STATUS, '') LEFT JOIN ( SELECT FACTORY_CODE, MATERIAL_CODE, LH_TYPE, FINISH_DATE, IFNULL(SUM(DAY_FINISH_QTY), 0) AS DAY_QTY FROM T_LH_DAY_FINISH_QTY WHERE IS_DELETE = 0 AND FINISH_DATE BETWEEN #{startDate} AND #{endDate} GROUP BY FACTORY_CODE, MATERIAL_CODE, LH_TYPE, FINISH_DATE ) fin ON fin.FACTORY_CODE = f5.FACTORY_CODE AND fin.MATERIAL_CODE = f5.MATERIAL_CODE AND IFNULL(fin.LH_TYPE, '') = IFNULL(f5.PRODUCT_STATUS, '') AND fin.FINISH_DATE >= IFNULL(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END, #{startDate}) AND fin.FINISH_DATE <= #{endDate} WHERE f5.IS_DELETE = 0 AND f5.YEAR = #{lastYear} AND f5.MONTH = #{lastMonth} AND f5.VERSION LIKE 'ADJ%' GROUP BY f5.FACTORY_CODE, f5.MATERIAL_CODE, f5.PRODUCT_STATUS, pv7.VERSION, stockMap.STOCK_CAPTURE_DATE, f5.DAY_1, f5.DAY_2, f5.DAY_3, f5.DAY_4, f5.DAY_5, f5.DAY_6, f5.DAY_7, f5.DAY_8, f5.DAY_9, f5.DAY_10, f5.DAY_11, f5.DAY_12, f5.DAY_13, f5.DAY_14, f5.DAY_15, f5.DAY_16, f5.DAY_17, f5.DAY_18, f5.DAY_19, f5.DAY_20, f5.DAY_21, f5.DAY_22, f5.DAY_23, f5.DAY_24, f5.DAY_25, f5.DAY_26, f5.DAY_27, f5.DAY_28, f5.DAY_29, f5.DAY_30, f5.DAY_31 ) calc ON f.FACTORY_CODE = calc.FACTORY_CODE AND f.MATERIAL_CODE = calc.MATERIAL_CODE AND IFNULL(f.PRODUCT_STATUS, '') = IFNULL(calc.PRODUCT_STATUS, '') AND f.VERSION = calc.CURRENT_ADJ_VERSION LEFT JOIN T_MP_FACTORY_PARAM fp ON fp.FACTORY_CODE = f.FACTORY_CODE AND fp.PRODUCT_TYPE_CODE = f.PRODUCT_TYPE_CODE AND fp.PARAM_CODE = #{overdueThresholdParamCode} AND fp.IS_DELETE = 0 SET f.LAST_MONTH_OVERDUE_QTY = IFNULL(calc.PLAN_QTY, 0) - IFNULL(calc.FINISH_QTY, 0), f.LAST_MONTH_VALID_FLAG = CASE WHEN ABS(IFNULL(calc.PLAN_QTY, 0) - IFNULL(calc.FINISH_QTY, 0)) > IFNULL(CAST(IFNULL(fp.PARAM_VALUE, fp.DEFAULE_VALUE) AS SIGNED), 0) THEN '0' ELSE '1' END, f.UPDATE_TIME = NOW() WHERE f.IS_DELETE = 0 AND f.YEAR = #{currentYear} AND f.MONTH = #{currentMonth} AND f.VERSION LIKE 'ADJ%'

mapper.select:
SELECT calc.FACTORY_CODE AS factoryCode, #{currentYear} AS year, #{currentMonth} AS month, procVer.VERSION AS version, f5.MONTH_PLAN_VERSION AS monthPlanVersion, NULL AS lastMonthPlanVersion, f5.PRODUCTION_VERSION AS productionVersion, '03' AS adjustType, calc.MATERIAL_CODE AS materialCode, f5.PRODUCT_STATUS AS productStatus, f5.PRODUCT_TYPE_CODE AS productTypeCode, f5.EMBRYO_CODE AS embryoCode, f5.BRAND AS brand, f5.SPECIFICATIONS AS specifications, f5.MAIN_PATTERN AS mainPattern, f5.PATTERN AS pattern, f5.CONSTRUCTION_STAGE AS constructionStage, f5.STRUCTURE_TYPE AS structureType, f5.STRUCTURE_NAME AS structureName, f5.MES_MATERIAL_CODE AS mesMaterialCode, f5.MATERIAL_DESC AS materialDesc, f5.MAIN_MATERIAL_DESC AS mainMaterialDesc, f5.PRO_SIZE AS proSize, f5.CX_MACHINE_CODE AS cxMachineCode, f5.MOULD_CAVITY_QTY AS mouldCavityQty, f5.TYPE_BLOCK_QTY AS typeBlockQty, f5.HEIGHT_QTY AS heightQty, f5.DAY_VULCANIZATION_QTY AS dayVulcanizationQty, NULL AS mouldChangeInfo, NULL AS hasSpecialMaterial, '0' AS isLockSchedule, '0' AS adjustFlag, 0 AS totalPlanQty, 0 AS totalQty, 0 AS heightProductionQty, 0 AS midProductionQty, 0 AS cycleProductionQty, 0 AS conventionProductionQty, 0 AS postponeProductionQty, 0 AS trialProductionQty, 0 AS differenceQty, NULL AS adjustDetailId, 0 AS beginDay, 0 AS endDay, calc.OVERDUE_QTY AS lastMonthOverdueQty, CASE WHEN ABS(calc.OVERDUE_QTY) > IFNULL(CAST(IFNULL(fp.PARAM_VALUE, fp.DEFAULE_VALUE) AS SIGNED), 0) THEN '0' ELSE '1' END AS lastMonthValidFlag FROM ( SELECT f5.FACTORY_CODE, f5.MATERIAL_CODE, f5.PRODUCT_STATUS, ( IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 1 THEN f5.DAY_1 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 2 THEN f5.DAY_2 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 3 THEN f5.DAY_3 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 4 THEN f5.DAY_4 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 5 THEN f5.DAY_5 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 6 THEN f5.DAY_6 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 7 THEN f5.DAY_7 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 8 THEN f5.DAY_8 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 9 THEN f5.DAY_9 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 10 THEN f5.DAY_10 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 11 THEN f5.DAY_11 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 12 THEN f5.DAY_12 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 13 THEN f5.DAY_13 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 14 THEN f5.DAY_14 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 15 THEN f5.DAY_15 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 16 THEN f5.DAY_16 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 17 THEN f5.DAY_17 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 18 THEN f5.DAY_18 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 19 THEN f5.DAY_19 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 20 THEN f5.DAY_20 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 21 THEN f5.DAY_21 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 22 THEN f5.DAY_22 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 23 THEN f5.DAY_23 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 24 THEN f5.DAY_24 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 25 THEN f5.DAY_25 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 26 THEN f5.DAY_26 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 27 THEN f5.DAY_27 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 28 THEN f5.DAY_28 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 29 THEN f5.DAY_29 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 30 THEN f5.DAY_30 ELSE 0 END, 0) + IFNULL(CASE WHEN DAYOFMONTH(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END) <= 31 THEN f5.DAY_31 ELSE 0 END, 0) ) - IFNULL(SUM(fin.DAY_QTY), 0) AS OVERDUE_QTY FROM T_MP_ADJUST_RESULT f5 LEFT JOIN (
SELECT #{item.factoryCode} AS FACTORY_CODE, #{item.materialCode} AS MATERIAL_CODE, #{item.productStatus} AS PRODUCT_STATUS, #{item.stockCaptureDate} AS STOCK_CAPTURE_DATE
) stockMap ON stockMap.FACTORY_CODE = f5.FACTORY_CODE AND stockMap.MATERIAL_CODE = f5.MATERIAL_CODE AND IFNULL(stockMap.PRODUCT_STATUS, '') = IFNULL(f5.PRODUCT_STATUS, '') LEFT JOIN ( SELECT FACTORY_CODE, MATERIAL_CODE, LH_TYPE, FINISH_DATE, IFNULL(SUM(DAY_FINISH_QTY), 0) AS DAY_QTY FROM T_LH_DAY_FINISH_QTY WHERE IS_DELETE = 0 AND FINISH_DATE BETWEEN #{startDate} AND #{endDate} GROUP BY FACTORY_CODE, MATERIAL_CODE, LH_TYPE, FINISH_DATE ) fin ON fin.FACTORY_CODE = f5.FACTORY_CODE AND fin.MATERIAL_CODE = f5.MATERIAL_CODE AND IFNULL(fin.LH_TYPE, '') = IFNULL(f5.PRODUCT_STATUS, '') AND fin.FINISH_DATE >= IFNULL(CASE WHEN stockMap.STOCK_CAPTURE_DATE BETWEEN #{startDate} AND #{endDate} THEN stockMap.STOCK_CAPTURE_DATE ELSE #{startDate} END, #{startDate}) AND fin.FINISH_DATE <= #{endDate} WHERE f5.IS_DELETE = 0 AND f5.YEAR = #{lastYear} AND f5.MONTH = #{lastMonth} AND f5.VERSION LIKE 'ADJ%' GROUP BY f5.FACTORY_CODE, f5.MATERIAL_CODE, f5.PRODUCT_STATUS, stockMap.STOCK_CAPTURE_DATE, f5.DAY_1, f5.DAY_2, f5.DAY_3, f5.DAY_4, f5.DAY_5, f5.DAY_6, f5.DAY_7, f5.DAY_8, f5.DAY_9, f5.DAY_10, f5.DAY_11, f5.DAY_12, f5.DAY_13, f5.DAY_14, f5.DAY_15, f5.DAY_16, f5.DAY_17, f5.DAY_18, f5.DAY_19, f5.DAY_20, f5.DAY_21, f5.DAY_22, f5.DAY_23, f5.DAY_24, f5.DAY_25, f5.DAY_26, f5.DAY_27, f5.DAY_28, f5.DAY_29, f5.DAY_30, f5.DAY_31 ) calc INNER JOIN T_MP_ADJUST_RESULT f5 ON f5.FACTORY_CODE = calc.FACTORY_CODE AND f5.MATERIAL_CODE = calc.MATERIAL_CODE AND IFNULL(f5.PRODUCT_STATUS, '') = IFNULL(calc.PRODUCT_STATUS, '') AND f5.YEAR = #{lastYear} AND f5.MONTH = #{lastMonth} AND f5.VERSION LIKE 'ADJ%' AND f5.IS_DELETE = 0 -- 取当月各分厂最新ADJ版本号 INNER JOIN ( SELECT FACTORY_CODE, MAX(VERSION) AS VERSION FROM T_MP_ADJUST_RESULT WHERE IS_DELETE = 0 AND YEAR = #{currentYear} AND MONTH = #{currentMonth} AND VERSION LIKE 'ADJ%' GROUP BY FACTORY_CODE ) procVer ON procVer.FACTORY_CODE = calc.FACTORY_CODE LEFT JOIN T_MP_FACTORY_PARAM fp ON fp.FACTORY_CODE = calc.FACTORY_CODE AND fp.PRODUCT_TYPE_CODE = f5.PRODUCT_TYPE_CODE AND fp.PARAM_CODE = #{overdueThresholdParamCode} AND fp.IS_DELETE = 0 -- 防重：当月调整结果表按相同维度(含VERSION)已存在的不插入 LEFT JOIN T_MP_ADJUST_RESULT exist ON exist.FACTORY_CODE = calc.FACTORY_CODE AND exist.MATERIAL_CODE = calc.MATERIAL_CODE AND IFNULL(exist.PRODUCT_STATUS, '') = IFNULL(calc.PRODUCT_STATUS, '') AND exist.VERSION = procVer.VERSION AND exist.YEAR = #{currentYear} AND exist.MONTH = #{currentMonth} AND exist.IS_DELETE = 0 WHERE exist.ID IS NULL AND calc.OVERDUE_QTY IS NOT NULL AND calc.OVERDUE_QTY <> 0

